xml.Script:
        Colors[0] := '0000C8'; // Blue
        Colors[1] := '800080'; // Purple
        Colors[2] := 'FF6000'; // Orange
        Colors[3] := '009600'; // Green
        Colors[4] := 'C80000'; // Red
        Colors[5] := 'FFFF00'; // Yellow
        Colors[6] := 'FFFFFF'; // White

        R := 0.6;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        H := R * (sqrt(5) - 1) / 2;
        N := 60; // sides of cylinder
        NC := 5; // colors
        N2 := N div NC;

        H2 := H * 1.1;
        H3 := H * 1.2;

        M := 6; // incline, even
        for i := 0 to N - 1 do begin
            x[i] := R * sin(2 * Pi / N * i);
            y[i] :=-R * cos(2 * Pi / N * i);

            j := (i + N2 div 2) mod N2 - N2 div 2;
            if j > M div 2 then
                zi[i] := H2
            else if j < -M div 2 then
                zi[i] :=-H2
            else
                zi[i] := H * sin(2*Pi / N * j) / sin(2*Pi / N * M/2);
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := (i + N) mod N;
i2 := (i + 1 + N) mod N;
Inc(i);
